typedef unsigned int u_int;
typedef float nglVector[4];
typedef float nglMatrix[4][4];
struct nglLightContext;
struct nglRenderParams
{
	u_int Flags;
	u_int TextureFrame;
	float ScrollU, ScrollV;
	nglVector TintColor;
	nglVector Scale;
	u_int MaterialMask;
	float ZBias;
	nglLightContext* LightContext;
	u_int NBones;
	nglMatrix* Bones;
};

enum { NGLP_SCALE = 0x40 };

struct WaterDebugStruct
{
	u_int BackfaceCull : 1;
	u_int BilinearFilter : 1;
	u_int DrawNearMesh : 1;
	u_int DrawSeamMesh : 1;
	u_int DrawSeamMeshDark : 1;
	u_int DrawSeamMeshHigh : 1;
	u_int DrawFarMesh : 1;
	u_int DrawFarMeshDark : 1;
	u_int DrawFarMeshHigh : 1;
	u_int DrawHorizonMesh : 1;
	u_int DrawTexture : 1;
	u_int DrawTextureAnim : 1;
	u_int DrawWaterMesh : 1;
	u_int FadeFarMesh : 1;
	u_int FadeHorizonMesh : 1;
	u_int FreezeWater : 1;
	u_int RecomputeExtents : 1;
	u_int ScissorNearMesh : 1;
	u_int ScissorSeamMesh : 1;
	u_int ScissorFarMesh : 1;
	u_int ScissorHorizonMesh : 1;
	u_int ShowNearLines : 1;
	u_int ShowSeamLines : 1;
	u_int ShowFarLines : 1;
	u_int ShowHorizonLines : 1;
	u_int TranparentNear : 1;
	u_int UniformGrid : 1;
	u_int UseLights : 1;
};

extern float WAVE_LocalScale[4];
extern nglMatrix WATER_LocalToWorld;
extern WaterDebugStruct WaterDebug;
extern u_int SeamWaterMeshID;
extern u_int FarWaterMeshID;
extern u_int HorizonWaterMeshID;
extern void WAVE_ListAdd(void);
extern void WAVETEX_SubmitMesh(
	u_int MeshID, const nglMatrix &LocalToWorld, nglRenderParams &Params,
	bool DrawMesh, bool DrawDark, bool DrawHighlight, bool DrawFoam, bool DrawSpecular);

__asm__(".equ WAVE_LocalScale, 0x00484690");
__asm__(".equ WATER_LocalToWorld, 0x0057B92C");
__asm__(".equ WaterDebug, 0x00484618");
__asm__(".equ SeamWaterMeshID, 0x0058EA34");
__asm__(".equ FarWaterMeshID, 0x0058EA38");
__asm__(".equ HorizonWaterMeshID, 0x0058EA3C");
__asm__(".equ WAVE_ListAdd__Fv, 0x00374930");
__asm__(".equ WAVETEX_SubmitMesh__FUiRC9nglMatrixR15nglRenderParamsbN43, 0x00381188");

void WATER_ListAdd(void)
{
	nglRenderParams rp;
	rp.Flags = NGLP_SCALE;
	rp.Scale[0] = WAVE_LocalScale[0];
	rp.Scale[1] = WAVE_LocalScale[1];
	rp.Scale[2] = WAVE_LocalScale[2];

	WAVE_ListAdd();

	if (WaterDebug.DrawWaterMesh && WaterDebug.DrawSeamMesh)
	{
		WAVETEX_SubmitMesh(SeamWaterMeshID, WATER_LocalToWorld, rp,
			WaterDebug.DrawSeamMesh, WaterDebug.DrawSeamMeshDark,
			WaterDebug.DrawSeamMeshHigh, WaterDebug.DrawSeamMeshHigh, true);
	}
	if (WaterDebug.DrawWaterMesh && WaterDebug.DrawHorizonMesh)
	{
		WAVETEX_SubmitMesh(HorizonWaterMeshID, WATER_LocalToWorld, rp,
			false, false, false, false, false);
	}
	if (WaterDebug.DrawWaterMesh && WaterDebug.DrawFarMesh)
	{
		WAVETEX_SubmitMesh(FarWaterMeshID, WATER_LocalToWorld, rp,
			WaterDebug.DrawFarMesh, WaterDebug.DrawFarMeshDark,
			WaterDebug.DrawFarMeshHigh, WaterDebug.DrawFarMeshHigh, true);
	}
}
